def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        colored = [c for c, value in enumerate(row) if value not in (8, 9)]
        if not colored:
            continue
        color = row[colored[0]]
        colored = [c for c in colored if row[c] == color]
        for left, right in zip(colored, colored[1:]):
            for c in range(left + 1, right):
                if row[c] in (8, 9):
                    out[r][c] = 2
    return out
